func (this *TreeTab) FindItem(value string, items []*swt.TreeItem) *swt.TreeItem {
	for _, item := range items {
		if item.GetText() == value {
			return item
		}
		item = this.FindItem(value, item.GetItems())
		if item != (nil) {
			return item
		}
	}
	return nil
}

