func (this *TreeTab) specialPopupMenuItems_(menu *swt.Menu, event *swt.Event) {
	var item *swt.MenuItem = swt.NewMenuItem(menu, swt.PUSH)
	item.SetText("getItem(Point) on mouse coordinates")
	var t *swt.Tree = castswtWidgetToswtTree(event.Widget)
	this.menuMouseCoords = t.ToControl(event.X, event.Y)
	item.AddSelectionListener(swt.SelectionListenerWidgetSelectedAdapter(func(e *swt.SelectionEvent) {
		this.eventConsole.Append(fmt.Sprintf("getItem(Point(%v)) returned: %v", this.menuMouseCoords, t.GetItemPoint(this.menuMouseCoords)))
		this.eventConsole.Append("\n")
	}))
}

